 obj={'id':f'C-SA21-{cote}-{n:03d}','items':[x['id'] for x in src],'cote':f'156-{cote}','scans':scans if scans is not None else sorted({v for x in src for v in x['scans'] if isinstance(v,int)}),'lines':lines or '; '.join(x['lines'] for x in src),'his_statement':quote or first['his_words'],'statement':statement or first['statement'],'status_on_pages':status,'computation':('audit/root_proofs.md#'+proof+'; code/root_checks.py and outputs/root_checks.json where a finite certificate is explicitly identified. No finite sample is used as a proof of an infinite axiom.' if proof else 'No numerical computation underlies this record. Definitions, quantified set constructions and proof obligations are distinguished in the statement.'),'class':cl,'fate':f['assessment'],'fate_date':date or {'manuscript':'June 1986','search_cutoff':'2026-11-19','exact_later_publication':'not located; see bounded search ledger'},'present_status':'As of 19 November 2026: '+present,'refs':refs if refs is not None else f['refs'],'confidence':confidence,'title':title,'role':role,'search_group':fam,'search_evidence':['sources_web/'+s for s in f['searches']]}
